DO $migration$ DECLARE src text; BEGIN src:=pg_get_functiondef('public.ocean_chest_tick(uuid)'::regprocedure); IF position('c.funded-c.reserved-c.earned-c.paid<max_ton' IN src)=0 THEN RAISE EXCEPTION 'Unexpected ocean budget definition'; END IF; src:=replace(src,'c.funded-c.reserved-c.earned-c.paid<max_ton','c.funded-c.reserved-c.earned-c.paid<max_ton OR (SELECT (value #>> ''{}'')::numeric FROM public.game_settings WHERE key=''ocean_chest_pool_ton'') < c.reserved+c.earned+c.paid+max_ton'); EXECUTE src; END $migration$;